{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "In healthy volunteers, tolfenamic acid had an absolute oral bioavailability averaging about 60% across oral doses of 100-800 mg compared with IV, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Saccharin, a small cyclic sulfonamide, had an absolute oral bioavailability of 0.84 ± 0.08 in fasted volunteers versus IV, supporting high oral bioavailability for the sulfonamide-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Meclofenamate, a chloro-substituted aromatic drug, has human oral bioavailability reported above 85%, supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Nifedipine, despite extensive first-pass metabolism, showed oral bioavailability of 45 ± 8% in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Clopenthixol, an orally administered antipsychotic, has absolute oral bioavailability of 40-60% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence consistently supports high oral bioavailability: multiple small-molecule drugs with high assay-transfer scores show absolute F values well above 20%, including tolfenamic acid (~60%), saccharin (~84%), meclofenamate (>85%), nifedipine (45-75%), and clopenthixol (40-60%). The query has favorable absorption properties and no labile ester prodrug motif, so the balance of evidence strongly favors F >= 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself is included in the evidence set.",
    "Metabolic stability and first-pass extraction of the query are not directly measured.",
    "The only low-F record (aspirin, ~17%) reflects presystemic ester hydrolysis to salicylate, a mechanism not applicable to the query's stable sulfonamide-isoindolinone structure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

